def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("Tag must be a string")
    if len(tag) < 1 or len(tag) > 10:
        raise ValueError("Tag must be between 1 and 10 characters long")
    if not tag.isalnum():
        raise ValueError("Tag must contain only letters and digits")
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not isinstance(node, xml.etree.ElementTree.Element):
        raise TypeError("node must be an ElementTree Element")

    children = node.getchildren()
    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            raise ValueError("duplicate tag: " + tag)
        result[tag] = child.text

    return result

