def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
            "properties": data["properties"]
        }
    except json.JSONDecodeError:
        pass

    try:
        xrd = XRD.parse(document)
        return {
            "subject": xrd.subject,
            "aliases": xrd.aliases,
            "links": xrd.links,
            "properties": xrd.properties
        }
    except XRD.ParseError:
        raise ValueError("Invalid Diaspora webfinger document")

    raise ValueError("Invalid Diaspora webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
