def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree

    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        response.raise_for_status()
        xml_data = response.content
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Error retrieving webfinger document: {e}")

    try:
        xml_root = ElementTree.fromstring(xml_data)
        webfinger_data = {}
        for child in xml_root:
            if child.tag == "{" + NS_DIASPORA + "}diaspora":
                webfinger_data["diaspora"] = {}
                for diaspora_child in child:
                    if diaspora_child.tag == "{" + NS_DIASPORA + "}handle":
                        webfinger_data["diaspora"]["handle"] = diaspora_child.text
                    elif diaspora_child.tag == "{" + NS_DIASPORA + "}publicKey":
                        webfinger_data["diaspora"]["publicKey"] = diaspora_child.text
        return webfinger_data
    except ElementTree.ParseError as e:
        raise ValueError(f"Error parsing webfinger document: {e}")
